// Recursive counting: a fork duplicates the REST of the program.
function processCount(prog) {
  function dem(ls) {
    if (!ls.length) return 1;
    const s = ls[0]; const rest = ls.slice(1);
    if (s.op === 'fork') return 2 * dem(rest);
    if (s.op === 'forkIf') return dem((s.who === 'parent' ? s.then : []).concat(rest)) + dem((s.who === 'child' ? s.then : []).concat(rest));
    return dem(rest);
  }
  return dem(prog);
}

function printCount(prog) {
  function dem(ls) {
    if (!ls.length) return 0;
    const s = ls[0]; const rest = ls.slice(1);
    if (s.op === 'print') return 1 + dem(rest);
    if (s.op === 'fork') return 2 * dem(rest);
    if (s.op === 'forkIf') return dem((s.who === 'parent' ? s.then : []).concat(rest)) + dem((s.who === 'child' ? s.then : []).concat(rest));
    return dem(rest);
  }
  return dem(prog);
}
